const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("AC-016 clicking Start hides #start", async ({ page }) => {
  await page.goto("index.html");
  await page.locator("#start").click();
  await expect(page.locator("#start")).toBeHidden();
});

